VALUES
    (1, 'IND-001', 'Air Charter Services Pvt. Ltd.', '+91 98718 01826', 'info@aircharterservices.com', 'https://www.aircharterservices.com', 1, 'India', ARRAY['VIDP', 'Delhi IGI Airport']::text[], ARRAY['India', 'International']::text[], ARRAY['charter', 'operator']::text[], ARRAY['Private jet charter', 'Helicopter charter', 'Air ambulance / medevac', 'Empty leg offers', 'Ground handling (Delhi)', 'VIP lounge access', 'In-flight catering']::text[], ARRAY['corporate', 'HNWI', 'medical']::text[], ARRAY['1 x Dassault Falcon 6X (large jet)', '1 x Dassault Falcon 2000LX (large jet)', '1 x Cessna Citation 560XL (midsize jet)', '1 x Cessna Citation CJ2+ (light jet)', '1 x Beechcraft King Air 200 (turboprop)', '1 x AgustaWestland A109S Grand (helicopter)']::text[], 'Delhi-based private aviation operator with a hangar at Indira Gandhi International Airport (Palam), offering jet charter, helicopter charter, and medevac. Operates a mixed fleet including Falcon 6X, Falcon 2000LX, Citation 560XL, Citation CJ2+, King Air 200, and an AW109S helicopter. Services are available 24/7 with in-house ground handling at Delhi.', 'medium', '2026-10-17', ARRAY['https://theflyingengineer.com/listing/charter/air-charter-services-pvt-ltd/', 'https://theflyingengineer.com/listing/air-charter-services-pvt-ltd/', 'https://aircharterservices.com/']::text[]),
    (2, 'IND-002', 'Club One Air', '+91 11 2677 9095', 'sales@cluboneair.com', 'https://www.cluboneair.com', 1, 'India', ARRAY['VIDP', 'Mumbai', 'Visakhapatnam']::text[], ARRAY['India']::text[], ARRAY['charter', 'operator']::text[], ARRAY['Private jet charter', 'Corporate travel']::text[], ARRAY['corporate', 'HNWI']::text[], ARRAY['5 x Dassault Falcon 2000 (large jet)', '2 x Cessna Citation Excel (midsize jet)', '1 x Cessna Citation II (light jet)', '1 x Bombardier CRJ100 (regional jet)']::text[], 'Indian private jet charter company operating primarily from Indira Gandhi International Airport, Delhi, with additional bases in Mumbai and Visakhapatnam. Fleet includes multiple Dassault Falcon 2000s, Cessna Citations, and a Bombardier CRJ100.', 'medium', '2026-10-17', ARRAY['https://en.wikipedia.org/wiki/Club_One_Air', 'https://theflyingengineer.com/listing/club-one-air/', 'https://www.cluboneair.com']::text[]),
    (3, 'IND-003', 'JetSetGo Aviation Services Pvt. Ltd.', '+91 11 4084 5858', 'Not publicly listed', 'https://www.jetsetgo.in', 1, 'India', ARRAY['VIDP', 'Mumbai', 'Bengaluru']::text[], ARRAY['India']::text[], ARRAY['charter', 'aircraft_management', 'operator']::text[], ARRAY['Private jet charter', 'Aircraft management', 'Maintenance contracts', 'Charter membership programs', 'Helicopter charter']::text[], ARRAY['corporate', 'HNWI', 'leisure']::text[], ARRAY['1 x Bombardier Global 6000 (large jet)', '1 x Embraer Legacy 600 (large jet)', '1 x Dassault Falcon 2000LX (large jet)', '1 x AgustaWestland AW109 (helicopter)']::text[], 'Founded in 2014 by Kanika Tekriwal and Sudheer Perla, JetSetGo is one of India''s largest private jet and helicopter operators. Headquartered in New Delhi, the company offers charter, aircraft management, and membership programs. Fleet of 12 aircraft including Bombardier Global 6000, Embraer Legacy 600, Falcon 2000LX, and helicopters.', 'high', '2026-10-17', ARRAY['https://en.wikipedia.org/wiki/JetSetGo', 'https://theflyingengineer.com/listing/charter/', 'https://jetsetgo.in/']::text[]),
    (4, 'IND-004', 'IndoPacific Aviation Services Pvt. Ltd.', 'Not publicly listed', 'Not publicly listed', 'https://www.indopacificaviation.com', 1, 'India', ARRAY['VIDP', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter', 'aircraft_management', 'operator']::text[], ARRAY['Private jet charter', 'Aircraft management (CAMO, crewing, dispatch)', 'MRO (CAR-145 approved)', 'Aircraft sourcing and sales', 'Aviation consultancy', 'Ground services coordination']::text[], ARRAY['corporate', 'HNWI', 'leisure']::text[], ARRAY['Not publicly verified']::text[], 'New Delhi-based private aviation company (part of the JetSetGo group) with headquarters at Nehru Place, South Delhi. Offers jet charter, full aircraft management including DGCA-compliant CAMO and crewing, CAR-145 approved MRO, and aircraft sourcing. Fleet includes light, midsize, large jets, and helicopters — specific models not publicly listed.', 'medium', '2026-10-17', ARRAY['https://theflyingengineer.com/listing/indopacific-aviation/']::text[]),
    (5, 'IND-005', 'India Fly Safe Aviation Ltd. (IFSAL)', '+91 78400 00473', 'info@safefly.aero', 'https://www.safefly.aero', 1, 'India', ARRAY['VIDP', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter', 'operator']::text[], ARRAY['Private jet charter', 'Helicopter charter', 'Air ambulance / medevac', 'Corporate shuttle programs', 'Aerial survey', 'Airport and helipad development and management', 'VIP charter']::text[], ARRAY['corporate', 'HNWI', 'medical', 'government']::text[], ARRAY['1 x AgustaWestland AW139 (helicopter)', '1 x AgustaWestland AW109S (helicopter)', '1 x Pilatus PC-12/NG (turboprop)', '1 x Embraer ERJ-135 (regional jet)', '1 x Cessna Caravan 208 (turboprop)']::text[], 'Established in 1997, India Fly Safe Aviation (IFSAL) is a New Delhi-based NSOP (non-scheduled operator) offering jet and helicopter charter, air ambulance, corporate shuttles, and aerial survey. Fleet of 12 aircraft and helicopters including AW139, AW109S, Pilatus PC-12/NG, ERJ-135, and Cessna Caravan.', 'medium', '2026-10-17', ARRAY['https://theflyingengineer.com/listing/india-fly-safe-aviation/', 'https://safefly.aero/contact-safe-fly-aviation/']::text[]),
    (6, 'IND-006', 'Deccan Charters Pvt. Ltd.', '+91 97400 32082', 'Not publicly listed', 'https://www.deccanair.com', 3, 'India', ARRAY['VIDP', 'Bengaluru', 'Chennai', 'Hyderabad', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter', 'aircraft_management', 'operator']::text[], ARRAY['Corporate travel', 'Aircraft management', 'Maintenance and technical services', 'Air charter', 'Air ambulance', 'UDAN regional routes']::text[], ARRAY['corporate', 'government', 'medical']::text[], ARRAY['5 x fixed-wing aircraft (types unspecified)', '12 x helicopters (types unspecified)']::text[], 'Bengaluru-headquartered operator with a major hub in New Delhi and operations across 15+ bases in India. Fleet of 17 aircraft (12 helicopters + 5 fixed-wing). Services include corporate travel, charter, air ambulance, MRO, aircraft management, and regional UDAN scheme flights. Note: HQ is Bengaluru, not Delhi NCR.', 'medium', '2026-10-17', ARRAY['https://theflyingengineer.com/listing/deccan-charters-private-limited/', 'https://deccanair.com']::text[]),
    (7, 'IND-007', 'Indamer Aviation Pvt. Ltd.', '+91 22 2661 5661', 'sales@indamer.com', 'http://www.indamer.com', 1, 'India', ARRAY['VIDP']::text[], ARRAY['India']::text[], ARRAY['fbo', 'support']::text[], ARRAY['FBO / ground handling at Delhi IGI', 'Aircraft line maintenance', 'Permit and handling services']::text[], ARRAY['corporate', 'government', 'HNWI']::text[], ARRAY['Not publicly verified']::text[], 'New Delhi-based FBO and ground handling provider operating at Indira Gandhi International Airport (VIDP). Also known through its subsidiary INDAMER MJETS AIRPORT SERVICES PVT LTD listed at ACUKWIK. Offers line maintenance, permit handling, and VIP ground services. Does not operate charter aircraft.', 'low', '2026-10-17', ARRAY['https://acukwik.com/Basic-Info/VIDP/INDAMER-MJETS-AIRPORT-SERVICES-PVT-LTD', 'https://marketplace.aviationweek.com/company/indamer-aviation-pvt-ltd', 'http://www.indamer.com']::text[]),
    (8, 'IND-008', 'Heritage Aviation', '+91 85888 30753', 'info@heritageaviation.in', 'https://www.heritageaviation.in', 1, 'India', ARRAY['VIDP', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter']::text[], ARRAY['Helicopter charter', 'Aircraft charter']::text[], ARRAY['corporate', 'HNWI']::text[], ARRAY['Not publicly verified']::text[], 'New Delhi-based helicopter and aircraft charter company. Listed as an air charter provider in India. Specific fleet and website could not be confirmed from public sources at the time of data collection.', 'low', '2026-10-17', ARRAY['https://theflyingengineer.com/cat/charter/in/india/']::text[]),
    (9, 'IND-009', 'AirLuxxis', '+91 95605 35566', 'contactus@airluxxis.com', 'https://airluxxis.com', 1, 'India', ARRAY['VIDP', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter', 'broker']::text[], ARRAY['Aircraft sales', 'Private jet charter', 'Aviation consulting']::text[], ARRAY['corporate', 'HNWI']::text[], ARRAY['Not publicly verified']::text[], 'New Delhi-based company offering aircraft sales (authorised Cirrus sales agent), private jet charter, and aviation consulting. Acts as a broker/agent rather than operating its own fleet. Specific website and contact details could not be confirmed from public sources at the time of data collection.', 'low', '2026-10-17', ARRAY['https://theflyingengineer.com/cat/charter/in/india/']::text[]),
    (10, 'IND-010', 'Span Air', '+91 11 2567 3006', 'Not publicly listed', 'http://www.spanair.in', 1, 'India', ARRAY['VIDP', 'New Delhi']::text[], ARRAY['India']::text[], ARRAY['charter', 'operator']::text[], ARRAY['Private executive charter']::text[], ARRAY['corporate', 'HNWI']::text[], ARRAY['Not publicly verified']::text[], 'New Delhi-based private executive charter company operating since 1995. One of India''s older NSOP providers. Specific fleet details and website could not be confirmed from public sources at the time of data collection.', 'low', '2026-10-17', ARRAY['https://theflyingengineer.com/cat/charter/in/india/']::text[]);

